INSERT INTO public.levels (number, name, short_description) VALUES (0, 'Formativo', 'Time recém-formado, entendendo quem é, por que existe e como se conecta à estratégia da empresa.')
INSERT INTO public.levels (number, name, short_description) VALUES (1, 'Reativo', 'Trabalho ainda reativo, com foco individual e primeiros passos de organização')
INSERT INTO public.levels (number, name, short_description) VALUES (2, 'Visível (Emergente)', 'Trabalho visível em um quadro único do time, início de cadências e políticas emergentes.')
INSERT INTO public.levels (number, name, short_description) VALUES (3, 'Definido', 'O quadro representa o fluxo de ponta a ponta, com etapas e políticas claras.')
INSERT INTO public.levels (number, name, short_description) VALUES (4, 'Gerenciado (Previsível)', 'Decisões guiadas por métricas de fluxo, previsibilidade e experimentos de melhoria contínua.')
INSERT INTO public.themes (id, name, description, narrative, display_order, active, created_at) VALUES ('81ea1062-5a65-4ded-bf76-de15da41fc0b', 'Propósito e Contexto', 'Quão claro é o propósito do time e como ele entende seu contexto dentro da empresa e do negócio.', 'Na reunião de priorização, três pessoas defendem três direções diferentes. Uma quer acelerar checkout, outra quer melhorar busca, outra quer corrigir bugs críticos. Sem clareza de propósito, cada sprint é uma batalha política — e o time nunca sabe se está ganhando ou perdendo.', 1, TRUE, '2025-12-02T13:01:35.683008+00:00');
INSERT INTO public.themes (id, name, description, narrative, display_order, active, created_at) VALUES ('f8e5618c-38f8-4cb4-b8a6-efcd60baa7cf', 'Visualização', 'Como o trabalho é tornado VISÍVEL: ferramentas, quadros, e indicadores que permitem VER o que está acontecendo.', 'Perguntam pro time: "o que está em andamento?" Silêncio. Alguém abre uma planilha desatualizada. Outro olha no Slack. Outro lembra de cabeça. Três fontes, três respostas diferentes. O trabalho existe, mas ninguém vê.', 2, TRUE, '2025-12-02T13:01:35.683008+00:00');
INSERT INTO public.themes (id, name, description, narrative, display_order, active, created_at) VALUES ('46f63e24-b5d0-4554-928b-eed0e3064807', 'Limite WIP', 'Como o time limita e gerencia o trabalho em progresso para manter foco e fluidez.', 'O time tem 5 pessoas e 17 itens "em progresso". Todo mundo começa tudo, ninguém termina nada. Quando o gestor pergunta "quando vai ficar pronto?", a resposta honesta seria: "quando alguém parar de me interromper com coisas novas".', 3, TRUE, '2025-12-02T13:01:35.683008+00:00');
INSERT INTO public.themes (id, name, description, narrative, display_order, active, created_at) VALUES ('fc7c28e6-ccf2-44dd-8509-03b13c9b344a', 'Gestão de Fluxo', 'Como o time mantém o trabalho em movimento contínuo: desobstruir impedimentos, priorizar término, e coordenar esforço coletivo.', 'O quadro mostra 8 itens em "Code Review" há uma semana. Ninguém move, ninguém pergunta, ninguém destrava. O fluxo parou, mas o time segue fingindo que está trabalhando — porque "tecnicamente" as tarefas estão em andamento.', 4, TRUE, '2025-12-02T13:01:35.683008+00:00');
INSERT INTO public.themes (id, name, description, narrative, display_order, active, created_at) VALUES ('fb87a002-ea38-4d66-878a-bd631ab7661c', 'Políticas e Definições de Pronto', 'Quão explícitas são as políticas de trabalho, critérios de entrada e saída e definições de pronto.', 'O dev diz: "terminei". O QA pergunta: "cadê os testes?". O dev: "não sabia que precisava". O PO: "mas não está em prod ainda". Três pessoas, três definições de "pronto". A história volta pro backlog.', 5, TRUE, '2025-12-02T13:01:35.683008+00:00');
INSERT INTO public.themes (id, name, description, narrative, display_order, active, created_at) VALUES ('86f56200-3c2a-4fb3-94dd-38b718661ac2', 'Melhoria Colaborativa', 'Como o time aprende junto, experimenta melhorias e trata problemas de forma coletiva.', 'Na retro, todo mundo reclama dos mesmos problemas de sempre. Anotam em post-its, tiram foto, mandam pro Slack. Na semana seguinte, ninguém lembra o que foi decidido. A retro virou terapia — desabafa e segue.', 6, TRUE, '2025-12-02T13:01:35.683008+00:00');
INSERT INTO public.themes (id, name, description, narrative, display_order, active, created_at) VALUES ('4d091505-772b-47d9-95a5-55664f66e016', 'Cadências e Rituais', 'Como o time usa dailies, plannings, retros e outras cerimônias para coordenar e melhorar o trabalho.', 'A daily acontece todo dia às 9h. O problema: ninguém sabe pra que serve. Cada pessoa fala o que fez, ninguém escuta, todo mundo sai aliviado que acabou. É ritual sem propósito — burocracia disfarçada de agilidade.', 7, TRUE, '2025-12-02T13:01:35.683008+00:00');
INSERT INTO public.themes (id, name, description, narrative, display_order, active, created_at) VALUES ('28bc7f52-0dbb-4b0d-87e6-38d91caba2b4', 'Cultura e Conhecimento', 'Nível de segurança psicológica, colaboração e distribuição de conhecimento dentro do time.', 'Pedro é o único que sabe como funciona o módulo de pagamentos. Quando ele sai de férias, o time para. Quando ele pede demissão, entra em pânico. O conhecimento estava na cabeça dele — e agora foi embora junto.', 8, TRUE, '2025-12-02T13:01:35.683008+00:00');
INSERT INTO public.themes (id, name, description, narrative, display_order, active, created_at) VALUES ('5d598ab4-a9f7-4fc9-870e-ba1ead448446', 'Métricas e Previsibilidade', 'Uso de métricas de fluxo e dados para tomar decisões e tornar o trabalho mais previsível.', 'O stakeholder pergunta: "conseguem entregar até o final do mês?". O time responde: "vamos tentar". Ninguém sabe o lead time real, ninguém olha throughput, ninguém mede nada. Toda promessa é chute — e todo chute vira cobrança.', 9, TRUE, '2025-12-02T13:01:35.683008+00:00');
INSERT INTO public.themes (id, name, description, narrative, display_order, active, created_at) VALUES ('381498e0-7e40-4a54-8343-aa6b3968eb7d', 'Quebra de Trabalho', 'Como o time quebra demandas grandes em partes menores e entregáveis, mantendo fluxo contínuo de valor.', 'Uma história entra como "melhorar a experiência do carrinho". Três semanas depois, ainda está "em desenvolvimento". O dev explica: "é que envolvia mais coisas do que a gente imaginava". Ninguém perguntou o óbvio: dava pra quebrar antes de começar?', 10, TRUE, '2025-12-03T14:14:52.639779+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('bbc7a80d-d69d-48f8-a519-f12981f8f231', 'fc7c28e6-ccf2-44dd-8509-03b13c9b344a', 1, 'Time percebe quando trabalho para, mas só age quando alguém reclama. Não há prática de manter movimento - impedimentos são conhecidos mas não tratados como prioridade.', 'Quando algo parar, defina: quem resolve? Até quando? Acompanhe no dia seguinte.', 'Todo mundo sabe que aquele item está travado há dias, mas cada um continua no seu.', 'Sentir que "demora muito" sem ter dados.', '2025-12-02T13:19:17.561038+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('4ce8156a-1e58-48b9-bd41-2dd0ad00e3a2', 'f8e5618c-38f8-4cb4-b8a6-efcd60baa7cf', 3, 'Quadro reflete o fluxo real de trabalho com colunas que representam etapas verdadeiras. Acúmulos são visíveis. Itens que estão há muito tempo numa coluna são destacados visualmente.', 'Adicione indicadores de aging no quadro: destaque visual para itens que estão há mais tempo que o esperado na mesma coluna.', 'Quadro com colunas que representam as etapas reais do trabalho. Fica visível onde os itens acumulam.', 'Visualizar bloqueios mas não agir sobre eles.', '2025-12-02T13:08:01.037093+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('d02bc018-cf26-4995-b2e0-b98130907803', 'fb87a002-ea38-4d66-878a-bd631ab7661c', 1, 'Existem definições informais sobre quando algo está "pronto". Algumas pessoas consultam critérios, outras não. Não há lista escrita, mas há noção compartilhada do que significa concluir.', 'Escreva numa lista simples: "para um item ser considerado pronto, precisa ter X, Y e Z". Deixe visível para consulta.', 'Pergunta "isso está pronto?" gera resposta parecida de pessoas diferentes, mas não há documento formal.', 'Definir "pronto" depois que já entregou.', '2025-12-02T13:19:17.561038+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('6c5ad77e-f521-42e9-abbf-3edbde3f25c5', 'fc7c28e6-ccf2-44dd-8509-03b13c9b344a', 2, 'Time ativamente mantém trabalho em movimento. Quando algo para, há ação imediata. Impedimentos têm dono e prazo. Desobstrução é prioridade antes de começar trabalho novo.', 'Pratique: ninguém puxa trabalho novo enquanto houver item desbloqueável esperando.', 'Na daily, bloqueio aparece e alguém assume: ''eu resolvo hoje''. Só depois de resolver é que puxa novo item.', 'Board com colunas genéricas que não refletem a realidade.', '2025-12-02T13:19:17.561038+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('234f2c49-e618-4a64-b57b-1374bc4af1b2', 'fc7c28e6-ccf2-44dd-8509-03b13c9b344a', 3, 'Time prioriza terminar antes de começar. Itens mais antigos têm prioridade sobre novos. Há consciência coletiva de que iniciar algo novo enquanto há trabalho próximo de terminar prejudica o fluxo.', 'Revise itens mais antigos primeiro na daily. Pergunte: ''o que pode terminar hoje?''', 'Quando há item na última coluna, alguém para o que está fazendo para ajudar a finalizar.', 'Medir mas não agir sobre os dados.', '2025-12-02T13:19:17.561038+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('df7a1901-a32b-4633-a4fa-dc4cb7356621', 'fb87a002-ea38-4d66-878a-bd631ab7661c', 2, 'Definições de pronto existem, estão escritas e visíveis. O time as consulta, mas ainda faz exceções "só dessa vez" com frequência. A consciência existe, a disciplina de seguir consistentemente ainda não.', 'Registre cada exceção: o que foi pulado e por quê. Revise mensalmente. Se a mesma exceção acontece toda vez, ou ajuste o critério ou resolva a causa raiz.', 'DoD está no quadro: "código revisado, testes passando, documentação atualizada". Mas às vezes passa sem review "porque é urgente".', 'DoD existe mas ninguém consulta.', '2025-12-02T13:19:17.561038+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('a1762be0-6674-4a3f-91fa-25497f5a1351', 'fb87a002-ea38-4d66-878a-bd631ab7661c', 3, 'Políticas são respeitadas consistentemente. Menos de 1 em cada 10 itens passa com exceção. Quando há exceção, ela é decidida explicitamente pelo time com registro do risco assumido. Trabalho raramente volta.', 'Adicione critérios de entrada além dos de saída: o que precisa existir ANTES de um item entrar em cada etapa. Isso previne problemas em vez de só detectá-los.', 'Dev pede "posso passar sem teste automatizado?". Time decide junto, registra débito técnico no backlog com prazo.', 'Políticas tão rígidas que ninguém segue.', '2025-12-02T13:19:17.561038+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('087411f2-f65d-4407-942a-ce3824a2cdd1', 'fc7c28e6-ccf2-44dd-8509-03b13c9b344a', 0, 'Não existe senso de continuidade. Cada pessoa trabalha no seu ritmo isolado. Quando algo para, simplesmente fica parado - não há urgência coletiva para manter o trabalho em movimento.', 'Comece a daily perguntando: ''tem algo parado?'' Identificar já é o primeiro passo.', 'Item fica dias sem progresso e ninguém percebe ou se importa até ser cobrado.', 'Achar que "flexibilidade" justifica caos no fluxo.', '2025-12-02T13:19:17.561038+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('f62de913-1c8b-4ba2-baca-40b97914ae34', 'fc7c28e6-ccf2-44dd-8509-03b13c9b344a', 4, 'Gestão de fluxo é proativa. Time observa o quadro, percebe acúmulos se formando, e redistribui esforço antes que virem gargalo. Não espera crise para agir.', 'Mantenha este nível revisando se práticas ainda funcionam. Ajuste conforme contexto muda.', 'Time percebe que revisão de código está acumulando e mobiliza ajuda antes de travar.', 'Usar dados só para reportar, não para melhorar.', '2025-12-02T13:19:17.561038+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('135d5611-64e0-477c-9b76-c816b6397ef6', '81ea1062-5a65-4ded-bf76-de15da41fc0b', 0, 'Ninguém consegue explicar em uma frase por que o time existe. Diferentes pessoas dão respostas diferentes sobre a missão. Decisões de priorização viram debate político — quem grita mais alto ou tem mais poder ganha.', 'Reúna o time e peça para cada pessoa escrever em um post-it: "nosso time existe para...". Compare as respostas. A divergência revelada é o primeiro passo para alinhar.', 'Na daily alguém pergunta "qual é o nosso objetivo?" e ninguém consegue responder. O time trabalha em demandas avulsas sem conexão entre si.', 'Achar que "entregar features" é propósito suficiente.', '2025-12-02T13:08:01.037093+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('217c99c3-f2e5-4802-8583-c48631649a44', '4d091505-772b-47d9-95a5-55664f66e016', 3, 'Rituais estão conectados e fluem naturalmente. Informações de um alimentam o outro. O ritmo é previsível e o time protege esses momentos. Participação é ativa, não passiva.', 'Revise a efetividade de cada ritual: o tempo gasto está gerando valor proporcional? Ajuste duração ou formato conforme necessário.', 'Decisões da planning são acompanhadas na daily. Tópicos levantados na daily viram pauta da retro quando recorrentes.', 'Cadências viram burocracia sem valor percebido.', '2025-12-02T13:19:47.984113+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('2390e2ea-b0a7-4d56-925c-dfb045cc80d4', '81ea1062-5a65-4ded-bf76-de15da41fc0b', 2, 'O propósito está documentado e é conhecido por todos. Quando chegam demandas conflitantes, o propósito começa a aparecer como critério de decisão — mas ainda não é usado consistentemente. Às vezes ganha quem insiste mais.', 'Na próxima demanda conflitante, use explicitamente o propósito como critério. Documente a decisão e o raciocínio. Repita até virar hábito.', 'Na planning, alguém diz "isso faz sentido para nosso propósito?" mas a demanda entra mesmo assim porque "o gerente pediu".', 'Saber o propósito mas não usar para priorizar.', '2025-12-02T13:08:01.037093+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('2be10eb1-da29-4108-9dcc-cd4e21993f34', '81ea1062-5a65-4ded-bf76-de15da41fc0b', 3, 'O time questiona demandas que não se alinham ao propósito. "Isso é nossa responsabilidade?" é pergunta comum e legítima. Escopo é defendido com base em critérios claros, não apenas em capacidade ou vontade.', 'Crie um documento de "O que NÃO fazemos" listando tipos de demanda que fogem do escopo. Use como referência quando chegarem pedidos fora de foco.', 'Time recusa uma demanda do stakeholder dizendo: "isso não se conecta com nossos objetivos, podemos negociar outra solução?".', 'Ter OKRs definidos mas não usá-los no dia a dia.', '2025-12-02T13:08:01.037093+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('ab0d1127-2f80-44eb-b090-81c4fa2c013e', '81ea1062-5a65-4ded-bf76-de15da41fc0b', 4, 'O time propõe iniciativas próprias baseadas em dados e contexto de negócio. Não espera ser alimentado — identifica oportunidades, valida hipóteses e argumenta por elas com evidências. Stakeholders confiam na direção que o time propõe.', 'Mantenha esse nível revisando trimestralmente se o propósito ainda reflete a estratégia. Compartilhe aprendizados sobre priorização com outros times.', 'Time identifica oportunidade de melhoria olhando dados de conversão e propõe experimento antes de qualquer pedido externo.', 'Autonomia sem prestação de contas sobre resultados.', '2025-12-02T13:08:01.037093+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('d50a6187-b19f-4026-8606-2c21c31ca913', '4d091505-772b-47d9-95a5-55664f66e016', 2, 'Cerimônias básicas acontecem regularmente com boa participação: daily todo dia, planning no início do ciclo, retrospectiva ao final. Estrutura existe e funciona. Mas os rituais ainda não estão conectados entre si — são eventos isolados.', 'Conecte os rituais: ações da retro viram itens no backlog. Problemas da daily alimentam a retro. Planning considera capacidade real baseada em histórico.', 'Daily foca no indivíduo. Planning define tarefas. Retro levanta problemas. Mas não há conexão clara entre elas.', 'Fazer cerimônias no automático sem propósito claro.', '2025-12-02T13:19:47.984113+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('0444a0ad-6b2e-40f3-84ab-1fc21cc7139a', '81ea1062-5a65-4ded-bf76-de15da41fc0b', 1, 'O propósito do time até existe na cabeça de alguns, mas não está explícito ou acessível. Cada pessoa entende sua função individual. Prioridades dependem de quem pede — não há critério compartilhado de decisão.', 'Documente o propósito do time em uma frase visível para todos. Valide com stakeholders se essa frase representa o que esperam do time.', 'Desenvolvedor sabe que trabalha com "checkout", mas não sabe qual métrica de negócio o checkout impacta ou quem são os clientes.', 'Conhecer só a parte técnica sem entender o valor para o cliente.', '2025-12-02T13:08:01.037093+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('a9d57066-7e24-4ed7-857f-50224a6aef7c', '4d091505-772b-47d9-95a5-55664f66e016', 1, 'Algumas cerimônias existem (daily, talvez planning), mas são vistas como obrigação burocrática. Acontecem porque "tem que fazer", não porque geram valor percebido. Pessoas chegam atrasadas ou multitask durante.', 'Revise o formato da daily: está ajudando a destravar trabalho? Se virou status report, mude o foco para bloqueios e colaboração.', 'Daily acontece às vezes. Quando acontece, dura 45 min e vira discussão técnica. Pessoas chegam atrasadas.', 'Transformar daily em reunião de 45 minutos.', '2025-12-02T13:19:47.984113+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('9824f7f6-ed1a-4f31-a83f-c33ee8c1cf66', '4d091505-772b-47d9-95a5-55664f66e016', 4, 'Cadências são otimizadas para o contexto específico do time. O time questiona e ajusta formato e frequência baseado em dados. Rituais que não geram valor são simplificados ou eliminados sem culpa.', 'Mantenha esse nível experimentando novos formatos. O que funciona para este time pode não funcionar daqui a 6 meses. Evolua junto com o contexto.', 'Time testou retro quinzenal em vez de semanal. Funcionou melhor. Mantiveram. Outro time faz diferente e tá ok.', 'Cadências perfeitas internamente mas desconectadas da organização.', '2025-12-02T13:19:47.984113+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('0dfd52cc-eec6-4950-a165-f3b99999ab37', '86f56200-3c2a-4fb3-94dd-38b718661ac2', 0, 'Problemas são tratados como falha individual. "Quem fez isso?" é pergunta mais comum que "que condição permitiu isso?". Não há espaço seguro para experimentar ou admitir erros. Culpa substitui aprendizado.', 'Na próxima vez que algo der errado, pergunte "o que no sistema permitiu esse erro?" em vez de "quem errou?". Documente a resposta.', 'Quando deploy quebra, primeira pergunta é "quem fez isso?". Pessoas escondem erros por medo de culpa.', 'Cultura de "cada um por si" para resolver problemas.', '2025-12-02T13:19:17.561038+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('ce145c72-d6ac-416d-8ef8-8ec7da64e776', '46f63e24-b5d0-4554-928b-eed0e3064807', 3, 'WIP é limitado por coluna do fluxo, não só por pessoa. Quando uma coluna atinge o limite, o time para para destravar antes de começar algo novo. Violações do limite são exceção discutida, não regra silenciosa.', 'Implemente sistema puxado: trabalho só entra no fluxo quando há capacidade comprovada. Monitore throughput semanal para validar se o ritmo está sustentável.', 'Review está no limite (3 itens). Devs param de começar novos itens e vão ajudar a revisar código dos colegas.', 'Respeitar WIP só quando conveniente.', '2025-12-02T13:08:01.037093+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('e9ac20fb-0630-406c-8450-b4f60d7cb6a0', '46f63e24-b5d0-4554-928b-eed0e3064807', 4, 'Sistema puxado maduro: trabalho só entra quando há capacidade real comprovada por dados. Ritmo é sustentável e previsível. O time ajusta limites periodicamente com base em throughput histórico e experimenta variações.', 'Mantenha esse nível refinando os limites com base em dados. Compartilhe aprendizados sobre gestão de WIP com outros times. Experimente limites diferentes para contextos diferentes.', 'Time percebe que lead time aumentou 20%. Reduz WIP de 5 para 4 para testar. Em 2 sprints, lead time normaliza.', 'WIP tão baixo que o time fica ocioso esperando.', '2025-12-02T13:08:01.037093+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('feba39ad-f051-49aa-8189-5ee21766bf40', 'fb87a002-ea38-4d66-878a-bd631ab7661c', 0, 'Não existem critérios explícitos de quando algo está pronto. Cada pessoa decide por conta própria. Dev acha que terminou, QA discorda, PO tem outra expectativa. Retrabalho é frequente porque "pronto" significa coisas diferentes.', 'Liste os últimos 5 itens que voltaram ou geraram retrabalho. Identifique o que faltou checar. Esse padrão mostra o que precisa entrar numa definição de pronto.', 'Dev marca item como "Done" sem teste. QA reclama que sempre recebe coisa incompleta. Discussões frequentes sobre "o que é pronto".', 'Assumir que todos entendem o que significa "terminado".', '2025-12-02T13:19:17.561038+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('60e024fc-04d0-4984-83fa-be97b144ac56', 'fb87a002-ea38-4d66-878a-bd631ab7661c', 4, 'Existem critérios de entrada E saída para cada etapa do fluxo. O time revisa políticas regularmente baseado em dados: "desde que adicionamos critério X, bugs em prod caíram Y%". Políticas evoluem com aprendizado.', 'Mantenha esse nível revisando políticas trimestralmente. Meça o impacto de cada mudança de critério. Compartilhe aprendizados com outros times.', 'Na retro trimestral, time revisa DoD: "Precisamos adicionar teste de acessibilidade? Nossos clientes pediram."', 'Políticas perfeitas no papel mas ignoradas na prática.', '2025-12-02T13:19:17.561038+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('742e9b30-5039-494b-92ab-9c4adb0b14cf', '86f56200-3c2a-4fb3-94dd-38b718661ac2', 1, 'Time faz retrospectivas, mas ações raramente são implementadas. Ideias ficam em post-its que ninguém revisa depois. Retro virou espaço para desabafar frustrações, não para mudar comportamentos ou processos.', 'Escolha UMA ação da última retro e transforme em item do backlog com dono e prazo. Na próxima retro, comece revisando se foi feita.', 'Retro gera 5 ações. Na próxima retro, nenhuma foi feita. "Não deu tempo." Mesmos problemas aparecem toda semana.', 'Buscar culpados em vez de causas raiz.', '2025-12-02T13:19:17.561038+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('b30aaca0-80b4-4a6c-94d9-a5f00ab389d1', '28bc7f52-0dbb-4b0d-87e6-38d91caba2b4', 0, 'Conhecimento crítico vive na cabeça de 1-2 pessoas. Quando essas pessoas faltam, tiram férias ou saem, o trabalho para. Não há documentação útil nem prática de compartilhamento. Silos são a norma aceita.', 'Mapeie: quais áreas do sistema só uma pessoa conhece? Liste os nomes. Esse mapa de risco é o ponto de partida para distribuir conhecimento.', 'Só o João sabe mexer no módulo X. Quando João tira férias, nada pode ser feito nessa área.', 'Aceitar silos de conhecimento como "especialização".', '2025-12-02T13:19:47.984113+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('2a7a9346-5fbb-4647-bc11-0e8bc0f570f4', '28bc7f52-0dbb-4b0d-87e6-38d91caba2b4', 1, 'O time sabe que tem silos e que isso é problema. Algumas pessoas criam documentação pessoal, mas ela fica desatualizada rapidamente e ninguém encontra quando precisa. Consciência do problema existe, ação coordenada não.', 'Implemente pair programming nas tarefas das áreas de maior risco (onde só 1 pessoa sabe). Objetivo: sempre 2 pessoas conhecendo cada área crítica.', 'João documentou o módulo X num wiki. Mas o documento está desatualizado e ninguém mais consegue operar.', 'Falar sobre compartilhar conhecimento mas não fazer.', '2025-12-02T13:19:47.984113+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('77a81185-c636-48dd-ac1d-2e46b0d2762c', '28bc7f52-0dbb-4b0d-87e6-38d91caba2b4', 2, 'Time usa pair programming ou mob programming em tarefas críticas para evitar dependência de pessoa única. Conhecimento começa a se distribuir. Pelo menos 2 pessoas conhecem cada área importante do sistema.', 'Crie regra explícita: nenhum módulo pode ter apenas um conhecedor. Monitore o mapa de conhecimento. Priorize distribuir nas áreas ainda concentradas.', 'Time faz pair programming 2x por semana. Maria agora também consegue mexer no módulo X, com ajuda.', 'Documentar tudo mas ninguém ler.', '2025-12-02T13:19:47.984113+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('a18b74c8-75b9-4822-bda8-1f055838e903', '28bc7f52-0dbb-4b0d-87e6-38d91caba2b4', 3, 'Existe regra explícita: nenhum módulo pode ter apenas um conhecedor. Time monitora ativamente onde há risco de concentração. Onboarding de novos membros é estruturado. O ambiente começa a encorajar perguntas sem julgamento.', 'Cultive segurança psicológica: perguntar "não sei fazer isso, me ensina?" deve ser normal e valorizado, não sinal de fraqueza.', 'Matriz de skills mostra: módulo X = João (expert), Maria (pode operar), Pedro (aprendendo). Sem silos críticos.', 'Generalistas forçados que não se aprofundam em nada.', '2025-12-02T13:19:47.984113+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('047a1c4d-2eec-4112-a30e-d2efa3715e6d', '86f56200-3c2a-4fb3-94dd-38b718661ac2', 4, 'Melhoria contínua é parte da cultura, não evento isolado. O time questiona status quo, compartilha aprendizados com outros times, e conecta experimentos com resultados de negócio. Aprender é tão valorizado quanto entregar.', 'Mantenha esse nível facilitando troca entre times. Apresente experimentos em fóruns mais amplos. Transforme aprendizados locais em conhecimento organizacional.', 'Time publica "learning report" mensal: o que testamos, o que aprendemos, o que mudamos. Outros times copiam práticas.', 'Experimentar tudo ao mesmo tempo sem medir nada.', '2025-12-02T13:19:17.561038+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('6b975b05-9bac-4a43-bc44-2fa54621ede9', 'f8e5618c-38f8-4cb4-b8a6-efcd60baa7cf', 4, 'Indicadores visuais automáticos (cores, alertas) destacam anomalias no fluxo. Time consulta o quadro antes de tomar decisões. Visualização é a principal ferramenta de gestão.', 'Mantenha esse nível revisando periodicamente se as visualizações ainda refletem o fluxo real. Compartilhe o modelo visual com outros times.', 'Itens que envelhecem ficam em vermelho automaticamente. Time olha o quadro antes de decidir o que priorizar.', 'Métricas visuais lindas que ninguém usa para decidir.', '2025-12-02T13:08:01.037093+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('2ae73da3-74b2-4ef5-bb34-c89746f06923', '86f56200-3c2a-4fb3-94dd-38b718661ac2', 2, 'Time discute problemas abertamente e busca soluções juntos. Há segurança para levantar questões sem medo de julgamento. Melhorias são tratadas como responsabilidade coletiva.', 'Reserve 10% do tempo do time para melhorias proativas (não apagar incêndio). Experimente uma melhoria por sprint, mesmo pequena, e meça o resultado.', 'Na retro, pessoas falam sobre o que não funcionou sem receio. Problemas são vistos como oportunidades de aprender.', 'Retro vira sessão de desabafo sem ações.', '2025-12-02T13:19:17.561038+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('85ea7e13-fd4f-4611-8c72-0c07701f3e50', '86f56200-3c2a-4fb3-94dd-38b718661ac2', 3, 'Melhorias identificadas viram ações concretas com dono e prazo. Time acompanha se as mudanças funcionaram. Há ciclo de experimentar, medir e ajustar.', 'Conecte experimentos com dados: "tentamos X, e o resultado foi Y". Documente aprendizados. Quando algo funciona, padronize. Quando não, aprenda e tente diferente.', 'Ação da retro tem responsável e data. Na retro seguinte, time revisa: "funcionou? ajustamos ou descartamos?".', 'Fazer melhorias mas nunca verificar se funcionaram.', '2025-12-02T13:19:17.561038+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('2c62c51b-3170-4485-b88c-8240be135f55', 'f8e5618c-38f8-4cb4-b8a6-efcd60baa7cf', 0, 'Não existe lugar comum para ver o trabalho do time. Cada pessoa sabe o que ela faz, mas ninguém tem visão do todo. Perguntar "o que está em andamento?" gera respostas diferentes de cada pessoa.', 'Peça para cada pessoa listar suas tarefas em andamento num post-it. Cole todos num mural ou quadro digital. Este é o primeiro passo para visibilidade compartilhada.', 'Pergunta ao colega "o que você está fazendo?" é a única forma de saber. Cada um tem anotações pessoais que ninguém mais vê.', 'Achar que "todo mundo sabe o que está fazendo" é suficiente.', '2025-12-02T13:08:01.037093+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('e4838301-83f5-4735-b609-760cf72d5f20', 'f8e5618c-38f8-4cb4-b8a6-efcd60baa7cf', 1, 'Cada pessoa tem sua lista de tarefas visível, mas não há quadro do time. O líder consolida informações manualmente quando precisa reportar. Duplicação de esforço acontece porque ninguém vê o que os outros estão fazendo.', 'Crie um quadro único do time (físico ou digital) e transfira todas as tarefas individuais para ele. Combine que todo trabalho novo entra ali.', 'Cada pessoa tem sua lista no Jira, mas não existe um board único do time. O líder atualiza uma planilha separadamente.', 'Board existe mas ninguém olha ou atualiza.', '2025-12-02T13:08:01.037093+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('c0c97ab3-7cd0-49cc-8c68-93f16989add2', '46f63e24-b5d0-4554-928b-eed0e3064807', 0, 'Não existe noção de limite. Cada pessoa trabalha em várias coisas simultaneamente. "Está em andamento" pode significar 10 itens diferentes para a mesma pessoa. Resultado: muito começa, pouco termina, tudo demora.', 'Pergunte a cada pessoa: "em quantas coisas você está trabalhando agora?". Some os números. O total provavelmente vai assustar — esse é o ponto de partida para a conversa.', 'Na daily, cada pessoa lista 4-5 itens "em andamento". Ninguém acha isso estranho. "Multitasking é normal aqui."', 'Achar que multitasking é produtividade.', '2025-12-02T13:08:01.037093+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('4d19fac8-3c6c-41c3-8735-970ccd51a846', '46f63e24-b5d0-4554-928b-eed0e3064807', 2, 'Existe limite de WIP por pessoa (ex: máximo 2 itens por vez). Quando alguém atinge o limite, não puxa trabalho novo até terminar algo. O time começa a experimentar dizer "não" ou "depois" para novas demandas urgentes.', 'Evolua o limite de "por pessoa" para "por coluna" do fluxo. Ex: coluna de Review só pode ter 3 itens. Quando estoura, alguém precisa revisar antes de continuar desenvolvendo.', 'Dev diz "não posso pegar mais, estou no meu limite". Mas a coluna "Em Review" tem 10 itens esperando.', 'Ter limite mas furar sempre "porque é exceção".', '2025-12-02T13:08:01.037093+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('48b19ad1-3889-4058-863f-5ebbff682b13', '4d091505-772b-47d9-95a5-55664f66e016', 0, 'Não há rituais regulares de coordenação. Comunicação acontece quando alguém precisa ou quando explode um problema. Alinhamento depende de encontros casuais, escalação, ou mensagens perdidas no Slack.', 'Implemente uma daily de 15 minutos no mesmo horário todo dia. Foco em: o que está travado e quem pode ajudar. Comece simples.', 'Time não tem daily. Pessoas descobrem que colega está bloqueado 3 dias depois quando pedem update.', 'Achar que "somos ágeis, não precisamos de reuniões".', '2025-12-02T13:19:47.984113+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('f83f7b52-d323-48cc-86da-3c69f08bfea5', '5d598ab4-a9f7-4fc9-870e-ba1ead448446', 0, 'Não há métricas de fluxo. Previsibilidade é baseada em feeling ou na pressão do stakeholder. Quando perguntam "quando fica pronto?", a resposta é um chute educado. Compromissos são baseados em esperança.', 'Comece a registrar quando cada item começa e quando termina. Só isso. Não precisa de ferramenta sofisticada — planilha serve. O hábito de medir é o primeiro passo.', 'PM pergunta "quando entrega?" Dev responde "acho que 2 semanas". Depois de 1 mês ainda não entregou.', 'Achar que estimar em story points resolve previsibilidade.', '2025-12-02T13:19:47.984113+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('14981047-7d7c-43ee-b94f-894457f6335f', '5d598ab4-a9f7-4fc9-870e-ba1ead448446', 1, 'Time coleta alguns dados (data de início e fim), mas não usa para decidir nada. Os números existem em algum lugar, mas ninguém consulta antes de responder uma pergunta de prazo.', 'Calcule o lead time médio dos últimos 20 itens. Use esse número na próxima vez que alguém perguntar "quando fica pronto?". Compare previsão com realidade.', 'Jira tem relatório de lead time. Ninguém olha. Estimativas continuam sendo chute baseado em pressão.', 'Medir velocidade sem entender o que significa.', '2025-12-02T13:19:47.984113+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('065a8eff-1583-44be-821b-411227ee3620', 'f8e5618c-38f8-4cb4-b8a6-efcd60baa7cf', 2, 'Existe um quadro único onde todo trabalho do time está visível. Colunas básicas (A Fazer, Fazendo, Feito) mostram status geral. Dá para ver quando algo está parado, mesmo que ainda não se aja sobre isso.', 'Mapeie com o time as etapas reais que um item percorre até ser entregue. Crie uma coluna para cada etapa no quadro.', 'Kanban do time com colunas claras. Itens bloqueados têm flag vermelha. Na daily, todos olham o quadro juntos.', 'Board bonito mas que não reflete a realidade do trabalho.', '2025-12-02T13:08:01.037093+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('d101fa0a-069f-4153-b896-be6fe183e961', '46f63e24-b5d0-4554-928b-eed0e3064807', 1, 'O time percebe que trabalhar em tudo ao mesmo tempo é problema. Surge consciência de que menos itens significam mais foco. Algumas pessoas experimentam limitar seu próprio trabalho.', 'Proponha ao time experimentar um limite pessoal: cada pessoa pode ter no máximo 2 itens em andamento. Teste por algumas semanas.', 'Alguém diz "preciso terminar isso antes de começar outra coisa". Há conversas sobre foco, mas não acordo formal.', 'Reclamar de contexto switching mas não fazer nada.', '2025-12-02T13:08:01.037093+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('d65c0b20-ee37-450e-a42c-d7b335d5fd8f', '5d598ab4-a9f7-4fc9-870e-ba1ead448446', 3, 'Métricas de fluxo são usadas ativamente: lead time, throughput, WIP. Time detecta anomalias e investiga quando uma métrica muda significativamente. Dados informam ações concretas de melhoria.', 'Evolua para percentis: em vez de "leva 10 dias em média", diga "85% dos itens terminam em até 14 dias". Isso comunica risco de forma mais honesta.', 'Time percebe no CFD que banda "em teste" está crescendo. Age antes de virar crise: "vamos ajudar QA esta semana".', 'Usar média para prever (ignora variabilidade).', '2025-12-02T13:19:47.984113+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('a9651052-7a17-4656-8ee5-f9b865d87eb1', '381498e0-7e40-4a54-8343-aa6b3968eb7d', 2, 'Existe prática de quebrar itens grandes antes de iniciar. Itens menores permitem feedback mais rápido. Time ainda não tem critério claro de tamanho, mas evita puxar itens muito grandes.', 'Defina com o time um critério simples de tamanho máximo. Pode ser baseado em tempo ou em escopo — o importante é ter referência.', 'Antes de começar, dev pergunta "dá pra quebrar isso?". Itens menores são preferidos mesmo sem regra formal.', 'Quebrar só histórias, mas deixar bugs e dívidas técnicas gigantes.', '2025-12-03T14:15:19.503781+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('f2a5180a-bc5c-4941-ac39-d39bd4488dbc', '381498e0-7e40-4a54-8343-aa6b3968eb7d', 3, 'Existe critério explícito de tamanho máximo que o time respeita. Itens que excedem são quebrados antes de entrar no fluxo. Entregas pequenas e frequentes são valorizadas.', 'Acompanhe se os itens entregues respeitam o critério de tamanho. Se muitos fogem do padrão, revise o critério com o time.', 'Time tem acordo: "se não cabe em uma iteração, quebramos". Refinamento inclui sempre a pergunta "dá pra dividir?".', 'Quebrar só por conveniência técnica, não por entrega de valor.', '2025-12-03T14:15:19.503781+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('c09cff89-f3ee-4be7-b17e-29d5348f2762', '5d598ab4-a9f7-4fc9-870e-ba1ead448446', 4, 'Previsibilidade madura com percentis (P50, P85) e análise probabilística. Stakeholder pergunta "quando?" e o time responde "85% de chance até dia X, 50% até dia Y". Compromissos são baseados em dados, não em pressão.', 'Mantenha esse nível compartilhando aprendizados com outros times. Revise periodicamente se as métricas ainda respondem às perguntas certas.', 'Para release grande, time roda simulação: "90% de chance de entregar 20 itens até dia 30". Stakeholder decide com dados.', 'Obsessão por métricas que vira microgerenciamento.', '2025-12-02T13:19:47.984113+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('f818d976-0199-4603-b781-499be306f27c', '381498e0-7e40-4a54-8343-aa6b3968eb7d', 0, 'Demandas entram grandes e permanecem grandes. Não há prática de quebrar trabalho em partes menores. Uma história pode ficar 3 semanas "em desenvolvimento" sem progresso visível nem feedback intermediário.', 'Pegue o maior item em andamento agora. Pergunte: "o que seria a menor parte disso que poderíamos entregar e receber feedback?". Quebre nessa parte.', 'Item no backlog: "Refatorar sistema de pagamentos". Fica 2 meses "em andamento" sem nada entregue.', 'Time acha normal ter itens abertos por 60+ dias sem questionar.', '2025-12-03T14:15:19.503781+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('dd3255d0-53b2-4ef9-9af3-b12a136bc55c', '381498e0-7e40-4a54-8343-aa6b3968eb7d', 1, 'Time tenta quebrar trabalho, mas pensa em tarefas técnicas (backend, frontend, testes). A quebra não gera entregas de valor intermediárias — só organiza internamente o trabalho. Usuário ainda espera semanas por resultado.', 'Mude a pergunta: em vez de "quais tarefas técnicas?", pergunte "qual a menor fatia de valor que o usuário pode ver?". Quebre por valor, não por componente.', 'Feature quebrada em: "criar tabela", "fazer API", "fazer tela". Só entrega valor quando tudo está junto.', 'Quebrar apenas na hora que já está atrasado, não no início.', '2025-12-03T14:15:19.503781+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('a659b272-ebe3-48cd-98ea-c5ad6dce9eaa', '381498e0-7e40-4a54-8343-aa6b3968eb7d', 4, 'Decomposição excelente é norma. Stakeholders entendem, valorizam e pedem entregas incrementais. Time nunca trabalha mais de 3 dias sem entregar algo tangível. Risco de projeto é distribuído em micro-entregas.', 'Mantenha esse nível experimentando técnicas diferentes de decomposição (story mapping, example mapping). Ensine outros times a quebrar trabalho efetivamente.', 'Feature grande é mapeada em story map. Time entrega fatia vertical por fatia, coletando feedback a cada entrega.', 'Foco excessivo em velocidade sem garantir que cada entrega tem valor.', '2025-12-03T14:15:19.503781+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('2ee3a44c-ea02-4ef5-b678-e249db9c399f', '28bc7f52-0dbb-4b0d-87e6-38d91caba2b4', 4, 'Segurança psicológica alta. Perguntar "não sei fazer isso" é normal e bem recebido. O time reserva tempo para ensinar. Conhecimento novo é compartilhado proativamente com outros times da organização.', 'Mantenha esse nível facilitando troca de conhecimento entre times. Crie espaços para compartilhar aprendizados. Documente padrões que podem ajudar outros.', 'Qualquer pessoa pode pegar qualquer tarefa. Time compartilha aprendizados espontaneamente. "Descobri isso, olha que legal!"', 'Cultura tão "segura" que ninguém dá feedback honesto.', '2025-12-02T13:19:47.984113+00:00');
INSERT INTO public.theme_level_descriptions (id, theme_id, level_number, description, next_step, examples, anti_patterns, created_at) VALUES ('43df046e-7096-48e3-b49a-098994baab8b', '5d598ab4-a9f7-4fc9-870e-ba1ead448446', 2, 'Lead time é monitorado e usado para dar estimativas. Time responde "itens parecidos levaram X a Y dias" em vez de chutar. Começa a perceber padrões: certos tipos de trabalho levam mais tempo.', 'Adicione throughput (quantos itens o time entrega por semana) às métricas. Com lead time + throughput, você tem base para previsões mais confiáveis.', 'Time sabe: "bugs levam em média 3 dias, features médias levam 8 dias". Usa isso para responder stakeholders.', 'Coletar dados mas guardar na gaveta.', '2025-12-02T13:19:47.984113+00:00');
