-- =====================================================================
-- Seed do CONTEUDO REAL do modelo (10 temas, 50 descricoes, 5 niveis)
-- =====================================================================
-- Por que existe: as migrations originais do Lovable semeavam apenas 7 temas
-- com nomes antigos ("Proposito & Contexto", "Visibilidade do Trabalho"...),
-- mas o app evoluiu para 10 temas com nomes novos ("Proposito e Contexto",
-- "Visualizacao", "Limite WIP"...) FORA dos arquivos de migration. Num banco
-- recriado do repo, o wizard ficava vazio. Este seed extrai o conteudo real do
-- banco original e o torna reproduzivel pelo proprio repo (independente do
-- Lovable). IDs preservados para manter as FKs consistentes.
-- Idempotente: limpa o conteudo de modelo e reinsere o conjunto correto.
-- (questions = 0 no original; a tabela segue sem uso.)
-- =====================================================================

-- Niveis (upsert por number)
  ON CONFLICT (number) DO UPDATE SET name = EXCLUDED.name, short_description = EXCLUDED.short_description;
  ON CONFLICT (number) DO UPDATE SET name = EXCLUDED.name, short_description = EXCLUDED.short_description;
  ON CONFLICT (number) DO UPDATE SET name = EXCLUDED.name, short_description = EXCLUDED.short_description;
  ON CONFLICT (number) DO UPDATE SET name = EXCLUDED.name, short_description = EXCLUDED.short_description;
  ON CONFLICT (number) DO UPDATE SET name = EXCLUDED.name, short_description = EXCLUDED.short_description;

-- Limpa o conteudo de modelo antigo (sem assessments no piloto; cascata segura)
DELETE FROM public.theme_level_descriptions;
DELETE FROM public.questions;
DELETE FROM public.themes;

